const shiftCash = `-- name: ShiftCash :one
SELECT
    COALESCE((SELECT sum(p.amount) FROM payments p WHERE p.property_id = $1 AND p.shift_id = $2::bigint AND p.payment_type = 'PAYMENT' AND p.payment_method = 'CASH' AND (p.status = 'POSTED' OR (p.status = 'VOIDED' AND p.voided_at >= $3::timestamptz))), 0)::numeric AS payments_in,
    COALESCE((SELECT sum(p.amount) FROM payments p WHERE p.property_id = $1 AND p.shift_id = $2::bigint AND p.payment_type = 'REFUND' AND p.payment_method = 'CASH' AND (p.status = 'POSTED' OR (p.status = 'VOIDED' AND p.voided_at >= $3::timestamptz))), 0)::numeric AS refunds_out,
    COALESCE((SELECT sum(r.amount) FROM city_ledger_receipts r WHERE r.property_id = $1 AND r.shift_id = $2::bigint AND r.payment_method = 'CASH' AND (r.status = 'POSTED' OR (r.status = 'VOIDED' AND r.voided_at >= $3::timestamptz))), 0)::numeric AS receipts_in,
    (COALESCE((SELECT sum(p.amount) FROM payments p JOIN cashier_shifts o ON o.property_id = p.property_id AND o.id = p.shift_id
                WHERE p.property_id = $1 AND p.shift_id <> $2::bigint AND p.payment_type = 'PAYMENT' AND p.payment_method = 'CASH' AND p.status = 'VOIDED'
                  AND p.voided_by = $4::bigint AND p.voided_at >= $5::timestamptz AND p.voided_at <= $3::timestamptz AND o.status = 'CLOSED' AND p.voided_at >= o.closed_at), 0)
   + COALESCE((SELECT sum(r.amount) FROM city_ledger_receipts r JOIN cashier_shifts o ON o.property_id = r.property_id AND o.id = r.shift_id
                WHERE r.property_id = $1 AND r.shift_id <> $2::bigint AND r.payment_method = 'CASH' AND r.status = 'VOIDED'
                  AND r.voided_by = $4::bigint AND r.voided_at >= $5::timestamptz AND r.voided_at <= $3::timestamptz AND o.status = 'CLOSED' AND r.voided_at >= o.closed_at), 0))::numeric AS voided_after_close,
    COALESCE((SELECT sum(m.amount) FROM cashier_shift_movements m WHERE m.property_id = $1 AND m.shift_id = $2 AND m.kind = 'PAY_IN'), 0)::numeric AS pay_ins,
    COALESCE((SELECT sum(m.amount) FROM cashier_shift_movements m WHERE m.property_id = $1 AND m.shift_id = $2 AND m.kind = 'PAY_OUT'), 0)::numeric AS pay_outs,
    COALESCE((SELECT sum(m.amount) FROM cashier_shift_movements m WHERE m.property_id = $1 AND m.shift_id = $2 AND m.kind = 'DROP'), 0)::numeric AS drops
`

